```js
import { logger } from './logger.js'
import { randomUUID } from 'crypto'
import client from 'prom-client'

// If these metrics already exist elsewhere in the registry, reuse that
// definition instead of redefining here — registering the same name twice
// throws in prom-client.
const chargeDuration = new client.Histogram({
  name: 'charge_duration_ms',
  help: 'Duration of charge() calls in milliseconds',
  buckets: [10, 50, 100, 250, 500, 1000, 2500, 5000],
})
const chargeTotal = new client.Counter({
  name: 'charge_requests_total',
  help: 'Total charge() calls',
})
const chargeErrors = new client.Counter({
  name: 'charge_errors_total',
  help: 'Total charge() failures',
  labelNames: ['error_type'],
})

export async function charge(order) {
  const correlationId = randomUUID()
  const start = process.hrtime.bigint()

  chargeTotal.inc()
  logger.info({ correlationId, service: 'billing', orderId: order?.id }, 'charge: entry')

  try {
    const res = await stripe.charges.create({ amount: order.total, source: order.token })

    const durationMs = Number(process.hrtime.bigint() - start) / 1e6
    chargeDuration.observe(durationMs)
    logger.info(
      { correlationId, service: 'billing', orderId: order?.id, durationMs, chargeId: res.id },
      'charge: exit'
    )

    return res.id
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1e6
    const errorType = err?.type || err?.name || 'unknown'
    chargeDuration.observe(durationMs)
    chargeErrors.inc({ error_type: errorType })
    logger.error(
      {
        correlationId,
        service: 'billing',
        orderId: order?.id,
        durationMs,
        errorType,
        message: err?.message,
        stack: err?.stack,
      },
      'charge: error'
    )
    throw err
  }
}
```

