## Tests for: `parseAge` (src/age.js)

Before writing anything: the stated contract — *"returns an integer age 0-150 for valid numeric strings and throws RangeError for anything else"* — does not match what the code actually does. `parseInt` silently returns `NaN` for garbage input, and `NaN < 0` / `NaN > 150` are both `false`, so the guard clause never fires for `null`, `undefined`, objects, empty strings, or non-numeric text — the function just returns `NaN` instead of throwing. It also happily parses `"12abc"` → `12` and `"0x10"` → `0` because `parseInt` stops at the first non-digit instead of rejecting malformed input outright. These are source bugs, not test defects — I'm writing tests against the stated contract, not the current implementation.

**Scenarios covered:**
- [x] Happy path: valid numeric string → integer
- [x] Boundary: 0, 150 (valid), -1, 151 (invalid), overflow to Infinity
- [x] Error: null, undefined, NaN, empty/whitespace string, non-numeric string, object, array, boolean, trailing-garbage string, decimal-fraction string, hex-prefixed string, injection-shaped string
- [x] External failure: N/A — pure function, no I/O, no dependencies
- [x] Concurrency: N/A — no shared/mutable state, calling twice is trivially idempotent and not a meaningful risk surface here

```js
// src/age.test.js
import { test, describe } from 'node:test'
import assert from 'node:assert/strict'
import { parseAge } from './age.js'

describe('parseAge', () => {
  describe('happy path', () => {
    test('should return 100 when input is "100"', () => {
      assert.equal(parseAge('100'), 100)
    })

    test('should return an integer when input is a valid numeric string', () => {
      const result = parseAge('42')
      assert.equal(Number.isInteger(result), true)
    })
  })

  describe('boundary conditions', () => {
    test('should return 0 when input is "0" (minimum valid age)', () => {
      assert.equal(parseAge('0'), 0)
    })

    test('should return 150 when input is "150" (maximum valid age)', () => {
      assert.equal(parseAge('150'), 150)
    })

    test('should throw RangeError when input is "-1" (one below minimum)', () => {
      assert.throws(() => parseAge('-1'), RangeError)
    })

    test('should throw RangeError when input is "151" (one above maximum)', () => {
      assert.throws(() => parseAge('151'), RangeError)
    })

    test('should throw RangeError when a numeric string overflows past double range to Infinity', () => {
      assert.throws(() => parseAge('9'.repeat(400)), RangeError)
    })
  })

  describe('invalid input — must throw RangeError per contract', () => {
    test('should throw RangeError when input is null', () => {
      assert.throws(() => parseAge(null), RangeError)
    })

    test('should throw RangeError when input is undefined', () => {
      assert.throws(() => parseAge(undefined), RangeError)
    })

    test('should throw RangeError when input is an empty string', () => {
      assert.throws(() => parseAge(''), RangeError)
    })

    test('should throw RangeError when input is a whitespace-only string', () => {
      assert.throws(() => parseAge('   '), RangeError)
    })

    test('should throw RangeError when input is a non-numeric string', () => {
      assert.throws(() => parseAge('abc'), RangeError)
    })

    test('should throw RangeError when input is a numeric prefix followed by trailing garbage', () => {
      assert.throws(() => parseAge('12abc'), RangeError)
    })

    test('should throw RangeError when input is the numeric value NaN', () => {
      assert.throws(() => parseAge(NaN), RangeError)
    })

    test('should throw RangeError when input is a plain object', () => {
      assert.throws(() => parseAge({}), RangeError)
    })

    test('should throw RangeError when input is an array', () => {
      assert.throws(() => parseAge([]), RangeError)
    })

    test('should throw RangeError when input is a boolean', () => {
      assert.throws(() => parseAge(true), RangeError)
    })

    test('should throw RangeError when input contains a decimal fraction', () => {
      assert.throws(() => parseAge('150.9'), RangeError)
    })

    test('should throw RangeError when input is a hex-prefixed string', () => {
      assert.throws(() => parseAge('0x10'), RangeError)
    })

    test('should throw RangeError when input has a leading digit followed by injection-shaped text', () => {
      assert.throws(() => parseAge('42; DROP TABLE users;'), RangeError)
    })
  })
})
```

**Coverage added:** both branches of the `if (n < 0 || n > 150)` guard, the implicit (and currently absent) "reject non-numeric/garbage input" path, both inclusive boundary edges (0 and 150), and the numeric-overflow path into `Infinity`.

